function factorValue(factors, path) { return path.split('.').reduce((value, key) => value?.[key], factors); }
function updateFactorValue(factors, path, value) {
  const next = { ...factors }; const keys = path.split('.'); let cursor = next; let source = factors;
  for (const key of keys.slice(0, -1)) { source = source?.[key] || {}; cursor[key] = { ...source }; cursor = cursor[key]; }
  cursor[keys.at(-1)] = value;
  return next;
}
function EditableFactorGroup({ group, factors, onChange }) {
  const Icon = group.icon;
  return <section className="factor-group factor-group-edit"><h4><span><Icon size={14}/></span>{group.title}</h4><div className="factor-items">{group.items.map(([label, path, type, unit, options]) => {
    const value = factorValue(factors, path);
    const field = type === 'select' ? <select aria-label={label} value={value ?? ''} onChange={e => onChange(path, e.target.value)}>{options.map(option => <option key={option}>{option}</option>)}</select>
      : type === 'boolean' ? <select aria-label={label} value={String(Boolean(value))} onChange={e => onChange(path, e.target.value === 'true')}><option value="true">Yes</option><option value="false">No</option></select>
      : <input aria-label={label} type={type === 'number' ? 'number' : 'text'} step={type === 'number' ? 'any' : undefined} value={type === 'number' && (value === null || value === undefined) ? '' : Array.isArray(value) ? value.join(', ') : value ?? ''} placeholder={type === 'number' ? '0' : ''} onChange={e => onChange(path, type === 'number' ? (e.target.value === '' ? '' : Number(e.target.value)) : e.target.value)} />;
    return <label className="factor-edit-item" key={path}><span>{label}</span><div>{field}{unit && <small>{unit}</small>}</div></label>;
  })}</div>{group.note && <p className="factor-note">{group.note}</p>}</section>;
}

